mapper.select:
select
pp.P_Id as pId,
pp.P_Name as pName,
pp.P_Code as pCode,
spp.*
    from Sec_Procurement_Plan spp left join Pre_Project pp on pp.P_ID= spp.p_id

    
        
            
                and likePname(#{params.pName},pp.P_Id)=true
            
            
                and pp.P_Name = #{params.pName}
            
        
    
    
        and spp.p_id = #{params.pId}
    
    
        and spp.plan_name like concat('%',#{params.planName},'%')
    
    
        and spp.plan_status = #{params.planStatus}
    
    
        and spp.plan_type = #{params.planType}
    
    
        and spp.plan_code = #{params.planCode}
    
    
        and spp.plan_form = #{params.planForm}
    
    
        and spp.plan_start_time = #{params.planStartTime}
    
    
        and spp.bidding_method = #{params.biddingMethod}
    
    
        and spp.state = #{params.state}
    
    
        and spp.state in
        
            #{state}
        
    
    
        and spp.state not in
        
            #{state}
        
    
    
        and pp.P_Name = #{params.pName}
    

order by spp.create_time desc
